import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in per-line `name=value` config text.

    Each line holds one `name=value` pair. Surrounding whitespace around the
    name and the value is ignored. Blank lines and lines starting with `#`
    (after stripping) are skipped. Only the first `=` separates name from
    value, so values may contain `=`. Returns an empty string when the key
    is absent. The function never reads files; `text` is the entire input.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_present_key() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_returns_empty_string_for_absent_key() -> None:
    assert config_value("host=localhost", "port") == ""


def test_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_strips_whitespace_around_name_and_value() -> None:
    assert config_value("  host  =   localhost  \n", "host") == "localhost"


def test_skips_comment_and_blank_lines() -> None:
    text = "# host=wrong\n\n   \nhost=right\n"
    assert config_value(text, "host") == "right"


def test_key_must_match_exactly() -> None:
    text = "ab=1\na=2"
    assert config_value(text, "a") == "2"
    assert config_value(text, "b") == ""


def test_value_may_contain_equals_sign() -> None:
    assert config_value("expr=a=b=c", "expr") == "a=b=c"


def test_line_without_equals_is_not_a_match() -> None:
    assert config_value("flagonly\nname=x", "flagonly") == ""


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("k=v", "k", "v"),
        ("k=", "k", ""),
        ("#k=v", "k", ""),
        ("x=1\ny=2\nz=3", "y", "2"),
    ],
)
def test_parametrized_cases(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected
